UPDATE activity_account
SET total_count_surplus = IF(total_count_surplus = -1, -1, total_count_surplus - 1),
    update_time = NOW()
WHERE user_id = #{userId}
  AND activity_id = #{activityId}
  AND (total_count_surplus > 0 OR total_count_surplus = -1)

UPDATE activity_account
SET month_count_surplus = month_count_surplus - 1,
    update_time = NOW()
WHERE user_id = #{userId}
  AND activity_id = #{activityId}
  AND month_count_surplus > 0

UPDATE activity_account
SET day_count_surplus = day_count_surplus - 1,
    update_time = NOW()
WHERE user_id = #{userId}
  AND activity_id = #{activityId}
  AND day_count_surplus > 0

UPDATE activity_account SET month_count = #{monthCount}, day_count = #{dayCount},
    update_time = NOW()
WHERE user_id = #{userId} AND activity_id = #{activityId}
